import 'package:flutter/material.dart'; import '../theme/app_colors.dart';
class PrimaryButton extends StatelessWidget{final String text;final VoidCallback? onTap;final bool outline,red;const PrimaryButton(this.text,{super.key,this.onTap,this.outline=false,this.red=false});@override Widget build(BuildContext c)=>SizedBox(width:double.infinity,child:FilledButton(style:FilledButton.styleFrom(backgroundColor:outline?Colors.transparent:red?AppColors.red:AppColors.green,foregroundColor:outline?AppColors.green:Colors.white,side:outline?const BorderSide(color:AppColors.green,width:1.5):null,padding:const EdgeInsets.all(14),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(14))),onPressed:onTap,child:Text(text,style:const TextStyle(fontSize:17,fontWeight:FontWeight.w800))));}
class AppCard extends StatelessWidget{final Widget child;final EdgeInsets? padding;const AppCard({super.key,required this.child,this.padding});@override Widget build(BuildContext c)=>Card(child:Padding(padding:padding??const EdgeInsets.all(14),child:child));}
class TopBar extends StatelessWidget{final String title;final Color? color;const TopBar(this.title,{super.key,this.color});@override Widget build(BuildContext c)=>Container(color:color??AppColors.green,padding:EdgeInsets.only(top:MediaQuery.paddingOf(c).top+8,bottom:12,left:16,right:8),child:Row(children:[IconButton(onPressed:()=>Navigator.maybePop(c),icon:const Icon(Icons.arrow_forward,color:Colors.white)),Text(title,style:const TextStyle(color:Colors.white,fontSize:19,fontWeight:FontWeight.w800))]));}
